    (v_guard->>'finalisation_week_ending')::date
  );

  -- Actual selected cohort/retained-route union first; no browser member,
  -- recipient, ordinal or clock acquires authority here.
  if cardinality(v_requested)>500 then raise exception 'WEEKLY_SOURCE_MANAGER_DIGEST_CAPACITY_EXCEEDED'using errcode='54000';end if;
  perform private.weekly_contact_source_manager_selection_lock_v1(v_requested,'[]');
  v_guard:=private.weekly_source_query_current_publication_v1(v_cycle_id,v_publication_id);
  perform private.weekly_source_office_authority_v1(v_actor,'SEND_MANAGER',(v_guard->>'source_group_id')::uuid,null,
    (v_guard->>'finalisation_week_ending')::date);
  v_contact_at:=clock_timestamp();
  for v_selected in select incident.id from public.weekly_discrepancy_incidents incident where incident.id=any(v_requested)order by incident.id loop
    v_contact_fact:=private.weekly_contact_manual_member_facts_v1(v_selected.id,'MANAGER',v_contact_at);
    if v_contact_fact->'eligible'is distinct from 'true'::jsonb and v_contact_fact->>'exclusion_reason'<>'MANUAL_ENQUIRY_COOLDOWN'
      or v_contact_fact->'cutoff'->'routine'->'in_scope'is distinct from 'true'::jsonb then
      raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE'using errcode='40001';end if;
    if v_contact_fact->>'cooldown_until_utc'is not null then
      v_contact_available:=greatest(v_contact_available,(v_contact_fact->>'cooldown_until_utc')::timestamptz);end if;
    if v_contact_fact->'last_accepted_send'='null'::jsonb then
      -- Preserve the genuine public initial owner's signed-work requirement.
      -- Other independently reviewed direct pending producers keep their ABI.
      if not exists(select 1 from public.weekly_discrepancy_incidents incident
        join public.weekly_issue_comparison_revisions comparison on comparison.id=incident.current_comparison_revision_id
        where incident.id=v_selected.id and comparison.candidate_timesheet_id is not null)then
        raise exception 'WEEKLY_SOURCE_MANAGER_REQUIRES_TIMESHEET'using errcode='55000';end if;
      v_initial_ids:=array_append(v_initial_ids,v_selected.id);v_followup:=null;
    else
      v_followup:=private.weekly_contact_source_manager_followup_state_v1(v_selected.id,v_contact_at);
      if v_followup->>'reason'is distinct from 'SCHEDULED'or v_followup->>'mode'is distinct from 'MANUAL'
        or(v_followup->>'due_at_utc')::timestamptz>v_contact_at then
        raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE'using errcode='40001';end if;
    end if;
    v_contact_members:=v_contact_members||jsonb_build_array(v_contact_fact||jsonb_build_object('followup_state',v_followup,
      'routine_step',v_followup->'routine_sequence','basis_accepted_membership_id',v_followup->'basis_accepted_membership_id'));
  end loop;

  for v_incident in
    select incident.*
    from public.weekly_discrepancy_incidents incident
    where incident.id=any(v_requested)
    order by incident.id
    for update
  loop
    if v_incident.source_cycle_id<>v_cycle_id or v_incident.state<>'OPEN'
       or v_incident.manager_potential_state<>'AVAILABLE'
       or private.weekly_source_covered_hours_incident_v1(v_incident.id)
       or v_incident.manager_action_state in ('RESPONDED','NOT_REQUIRED') then
      raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE' using errcode='40001';
    end if;
    select * into strict v_comparison from public.weekly_issue_comparison_revisions
    where id=v_incident.current_comparison_revision_id;
    select value into strict v_contact_member from jsonb_array_elements(v_contact_members)where value->>'issue_id'=v_incident.id::text;
    v_contact_fact:=private.weekly_contact_manual_member_facts_v1(v_incident.id,'MANAGER',v_contact_at);
    if(v_contact_fact-array['recipient_route_id','cooldown_remaining_seconds'])is distinct from(
      v_contact_member-array['recipient_route_id','cooldown_remaining_seconds','followup_state','routine_step','basis_accepted_membership_id'])then
      raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE'using errcode='40001';end if;
    if v_incident.id=any(v_initial_ids)and v_comparison.candidate_timesheet_id is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_REQUIRES_TIMESHEET' using errcode='55000';
    end if;
    select * into strict v_event from public.weekly_work_events where id=v_incident.work_event_id;
    v_context:=private.weekly_source_query_cohort_ensure_v1(
      v_cycle_id,v_incident.candidate_id,v_incident.client_id,
      v_comparison.contract_id,v_event.work_date
    );
    if coalesce((v_context->>'manager_queries_enabled')::boolean,false) is not true
       or nullif(v_context->>'manager_route_id','') is null then
      raise exception 'WEEKLY_SOURCE_MANAGER_QUERIES_DISABLED' using errcode='55000';
    end if;
    v_current_route_id:=(v_context->>'manager_route_id')::uuid;
    if v_route_id is null then v_route_id:=v_current_route_id;
    elsif v_route_id<>v_current_route_id then
      raise exception 'WEEKLY_SOURCE_MANAGER_SEND_ONE_RECIPIENT_REQUIRED' using errcode='22023';
    end if;
    if v_incident.id=any(v_initial_ids)and not ((v_context->>'cohort_id')::uuid=any(v_selected_cohort_ids)) then
      v_selected_cohort_ids:=pg_catalog.array_append(
        v_selected_cohort_ids,(v_context->>'cohort_id')::uuid
      );
    end if;
    v_key:=v_incident.candidate_id::text||':'||v_incident.client_id::text;
    if v_incident.id=any(v_initial_ids)and not (v_key=any(v_seen_keys)) then
      v_seen_keys:=pg_catalog.array_append(v_seen_keys,v_key);
      insert into public.weekly_route_activations(
        source_cycle_id,candidate_id,client_id,audience_route,route_mode,
        activated_by_user_id,activated_at_utc,updated_at_utc
      ) values (
        v_cycle_id,v_incident.candidate_id,v_incident.client_id,'MANAGER','MANAGER_DIRECT',
        v_actor,pg_catalog.transaction_timestamp(),pg_catalog.transaction_timestamp()
      ) on conflict (source_cycle_id,candidate_id,client_id,audience_route)
      do update set route_mode='MANAGER_DIRECT',
        activated_by_user_id=excluded.activated_by_user_id,
        activated_at_utc=coalesce(public.weekly_route_activations.activated_at_utc,excluded.activated_at_utc),
        updated_at_utc=excluded.updated_at_utc;
    end if;
  end loop;
  if (select pg_catalog.count(*) from public.weekly_discrepancy_incidents where id=any(v_requested))
     <>pg_catalog.array_length(v_requested,1) then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE' using errcode='40001';
  end if;
  if exists(
    select 1
    from public.weekly_candidate_cohorts cohort
    join public.weekly_discrepancy_incidents incident
      on incident.source_cycle_id=cohort.source_cycle_id
     and incident.candidate_id=cohort.candidate_id
     and incident.client_id=cohort.client_id
     and incident.state='OPEN'
     and incident.manager_potential_state='AVAILABLE'
     and incident.manager_action_state not in ('RESPONDED','NOT_REQUIRED')
    join public.weekly_issue_comparison_revisions comparison
      on comparison.id=incident.current_comparison_revision_id
     and comparison.candidate_timesheet_id is not null
    where cohort.id=any(v_selected_cohort_ids)
      and not private.weekly_source_covered_hours_incident_v1(incident.id)
      and not (incident.id=any(v_requested))
  ) then
    raise exception 'WEEKLY_SOURCE_MANAGER_SEND_SELECTION_STALE' using errcode='40001';
